// node test/timeline.test.mjs (from this folder) -- the model, without a browser
// THIS SECTION GENERATED BY CLAUDE
import { makeTimeline, valueAt } from '../timeline.js'
import { makeRegistry } from '../registry.js'
import { makeZip, crc32 } from '../zip.js'
import assert from 'node:assert/strict'

let near = (a, b, eps = 1e-9) => assert.ok(Math.abs(a - b) < eps, `${a} != ${b}`)

// interpolation
let T = makeTimeline({ fps: 10, duration: 4 })
let k = T.addTrack('x', 'linear')
T.setKey(k, 2, 20); T.setKey(k, 0, 0); T.setKey(k, 1, 10)         // out of order in, sorted out
assert.deepEqual(k.keys.map(x => x.t), [0, 1, 2])
near(valueAt(k, 0.5), 5); near(valueAt(k, -1), 0); near(valueAt(k, 9), 20)
k.interp = 'smooth'; near(valueAt(k, 0.5), 5); near(valueAt(k, 0.25), 10 * 0.15625)
k.interp = 'step'; near(valueAt(k, 0.99), 0); near(valueAt(k, 1), 10)
k.interp = 'spline'; near(valueAt(k, 1), 10); near(valueAt(k, 0.5), 5)    // through the keys, linear data stays linear
k.keys[0].ease = 'in'; k.interp = 'linear'; near(valueAt(k, 0.5), 2.5)
assert.equal(T.addTrack('x'), k)                                       // one track per property
T.setKey(k, 1.02, 99); assert.equal(k.keys.length, 3); assert.equal(k.keys[1].v, 99)   // within half a frame: replaced

// arrays, componentwise
let c = T.addTrack('cam')
T.setKey(c, 0, [0, 100]); T.setKey(c, 2, [10, 0])
assert.deepEqual(valueAt(c, 1), [5, 50])
assert.deepEqual(T.sample(1), { x: 99, cam: [5, 50] })
assert.equal(T.valueAt(T.addTrack('empty'), 1), undefined)
assert.equal(T.frames(), 40); near(T.snap(0.26), 0.3); near(T.extent(), 2)

// json round trip
let j = JSON.parse(JSON.stringify(T.toJSON()))
let U = makeTimeline().fromJSON(j)
assert.deepEqual(U.toJSON(), T.toJSON())
assert.equal(U.track('x').keys[0].ease, 'in')
T.deleteKey(k, k.keys[0]); assert.equal(k.keys.length, 2)
T.removeTrack('x'); assert.equal(T.track('x'), undefined)

// registry coercion
let S = { n: 0, e: 0, v: [0, 0], f: 0 }
let R = makeRegistry()
R.add({ id: 'n', min: 0, max: 10, step: 1, get: _ => S.n, set: v => S.n = v })
R.add({ id: 'e', options: { a: 0, b: 5 }, get: _ => S.e, set: v => S.e = v })
R.add({ id: 'v', dims: 2, min: -1, max: 1, get: _ => S.v, set: v => S.v = v })
R.add({ id: 'f', get: _ => S.f, set: v => S.f = v })
assert.deepEqual(R.apply({ n: 3.6, e: 2, v: [5, -0.5], f: 0.123, zz: 1 }), ['n', 'e', 'v', 'f'])
assert.deepEqual(S, { n: 4, e: 0, v: [1, -0.5], f: 0.123 })
assert.equal(R.get('e').interp, 'step')
R.apply({ n: 99 }); assert.equal(S.n, 10)
assert.deepEqual(R.current('v'), [1, -0.5]); assert.notEqual(R.current('v'), S.v)

// zip
assert.equal(crc32(new TextEncoder().encode('123456789')), 0xcbf43926)
let chunks = []
let z = makeZip({ write: b => chunks.push(b) })
z.add('a.txt', new TextEncoder().encode('hello'))
z.add('b.txt', new TextEncoder().encode('world!'))
assert.equal(await z.finish(), null)
let all = new Uint8Array(chunks.reduce((n, c) => n + c.length, 0)), o = 0
for (let ch of chunks) { all.set(ch, o); o += ch.length }
assert.deepEqual([...all.slice(0, 4)], [0x50, 0x4b, 3, 4])
let end = all.length - 22
assert.deepEqual([...all.slice(end, end + 4)], [0x50, 0x4b, 5, 6])
assert.equal(all[end + 10] | (all[end + 11] << 8), 2)                     // two entries
console.log('timeline tests: ok')
